import{_ as e,c as t,o as i,ag as r}from"./chunks/framework.D2yTFDqz.js";const g=JSON.parse('{"title":"2025.1.3","description":"","frontmatter":{"title":"2025.1.3"},"headers":[],"relativePath":"changelog/latest.md","filePath":"changelog/latest.md","lastUpdated":1765114933000}'),l={name:"changelog/latest.md"};function o(n,a,s,h,d,c){return i(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="📢-view-shadcn-ui-v2025-1-4-发布-全面拥抱暗黑模式" tabindex="-1">📢 View Shadcn UI v2025.1.4 发布 - 全面拥抱暗黑模式 <a class="header-anchor" href="#📢-view-shadcn-ui-v2025-1-4-发布-全面拥抱暗黑模式" aria-label="Permalink to &quot;📢 View Shadcn UI v2025.1.4 发布 - 全面拥抱暗黑模式&quot;">​</a></h1><p>我们很高兴地宣布，View Shadcn UI v2025.1.4 版本已于 2025 年 12 月 7 日正式发布！这是一个重要的里程碑版本，为整个组件库带来了全面的暗黑模式支持。</p><h3 id="📋-版本信息" tabindex="-1">📋 版本信息 <a class="header-anchor" href="#📋-版本信息" aria-label="Permalink to &quot;📋 版本信息&quot;">​</a></h3><ul><li><strong>版本号</strong>: 2025.1.4</li><li><strong>发布日期</strong>: 2025 年 12 月 7 日</li><li><strong>项目地址</strong>: <a href="https://github.com/devlive-community/view-shadcn-ui" target="_blank" rel="noreferrer">https://github.com/devlive-community/view-shadcn-ui</a></li><li><strong>官方网站</strong>: <a href="https://view-shadcn-ui.devlive.org/" target="_blank" rel="noreferrer">https://view-shadcn-ui.devlive.org/</a></li><li><strong>演练场</strong>: <a href="https://playground.view-shadcn-ui.devlive.org/" target="_blank" rel="noreferrer">https://playground.view-shadcn-ui.devlive.org/</a></li></ul><h3 id="🌟-主要更新" tabindex="-1">🌟 主要更新 <a class="header-anchor" href="#🌟-主要更新" aria-label="Permalink to &quot;🌟 主要更新&quot;">​</a></h3><h4 id="🌙-全面暗黑模式支持" tabindex="-1">🌙 全面暗黑模式支持 <a class="header-anchor" href="#🌙-全面暗黑模式支持" aria-label="Permalink to &quot;🌙 全面暗黑模式支持&quot;">​</a></h4><p>本次更新的核心是为所有组件添加了完整的暗黑模式支持，让您的应用可以轻松切换明暗主题，提供更好的用户体验。</p><p><strong>已支持暗黑模式的组件</strong>：</p><ul><li><strong>布局组件</strong>：布局（Layout）</li><li><strong>表单组件</strong>：输入标签（Input Tags）、切换（Switch）、复选框（Checkbox）、颜色选择器（Color Picker）</li><li><strong>反馈组件</strong>：警告提示（Alert）、徽章（Badge）、提示（Tooltip）</li><li><strong>导航组件</strong>：面包屑（Breadcrumb）、返回顶部（Back to Top）</li><li><strong>展示组件</strong>：头像（Avatar）、卡片（Card）、折叠面板（Collapse）、轮播（Carousel）、抽屉（Drawer）</li><li><strong>操作组件</strong>：按钮（Button）、右键菜单（Context Menu）</li><li><strong>高级组件</strong>：数据表格（Data Table）、代码编辑器（Code Editor）、计划任务（Cron）</li></ul><h4 id="🔧-数据表格增强" tabindex="-1">🔧 数据表格增强 <a class="header-anchor" href="#🔧-数据表格增强" aria-label="Permalink to &quot;🔧 数据表格增强&quot;">​</a></h4><p>除了暗黑模式支持外，我们还对数据表格组件进行了多项功能增强：</p><ul><li>✅ 修复了悬停固定列的显示问题</li><li>✅ 支持自定义表格样式</li><li>✅ 支持表头自定义插槽</li><li>✅ 支持数据列自定义插槽</li><li>✅ 支持表格边框配置</li><li>✅ 支持固定列功能</li></ul><h3 id="💡-关于-view-shadcn-ui" tabindex="-1">💡 关于 View Shadcn UI <a class="header-anchor" href="#💡-关于-view-shadcn-ui" aria-label="Permalink to &quot;💡 关于 View Shadcn UI&quot;">​</a></h3><p>View Shadcn UI 是一个基于 Tailwind CSS 构建的现代化 Vue3 组件库，致力于提供优雅、高效且易于使用的 UI 组件，帮助开发者快速构建美观的用户界面。</p><h3 id="🙏-致谢" tabindex="-1">🙏 致谢 <a class="header-anchor" href="#🙏-致谢" aria-label="Permalink to &quot;🙏 致谢&quot;">​</a></h3><p>感谢社区所有贡献者和用户的支持与反馈，让 View Shadcn UI 变得更加完善！</p>',16)])])}const p=e(l,[["render",o]]);export{g as __pageData,p as default};
